<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use Illuminate\Http\{JsonResponse,Request};use Illuminate\Support\Facades\Auth;
class AuthController extends Controller{public function login(Request $r):JsonResponse{$data=$r->validate(['email'=>['required','email'],'password'=>['required','string'],'remember'=>['sometimes','boolean']]);if(!Auth::attempt(['email'=>$data['email'],'password'=>$data['password'],'is_admin'=>true],$data['remember']??false))return response()->json(['message'=>'The provided credentials are incorrect.'],422);$r->session()->regenerate();return response()->json(['data'=>$r->user()->only('id','name','email')]);}public function me(Request $r):JsonResponse{return response()->json(['data'=>$r->user()->only('id','name','email')]);}public function logout(Request $r):JsonResponse{Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return response()->json(['message'=>'Logged out.']);}}
